function bubbleSort(arr) {
  var len = arr.length;
  var swapped;
  do {
    swapped = false;
    for (var i = 0; i < len; i++) {
      if (arr[i] > arr[i + 1]) {
        var temp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = temp;
        swapped = true;
